try:
    import unittest2 as unittest
except ImportError:
    import unittest  # type: ignore

from taf.cloud.cbam.schemas.v4.vnf_lcm_op_occ import VnfLcmOpOccLinks, VnfLcmOpOcc


class TestVnfLcmOpOccLinks(unittest.TestCase):
    def setUp(self):
        self.self_link = 'arg1'
        self.list_link = 'arg2'
        self.cancel = 'arg3'
        self.fail = 'arg4'
        self.vnf_instance = 'arg5'
        self.grant = 'arg6'
        self.links_dict = {'self': {'href': self.self_link}, 'list': {'href': self.list_link},
                           'cancel': {'href': self.cancel}, 'fail': {'href': self.fail},
                           'vnfInstance': {'href': self.vnf_instance}, 'grant': {'href': self.grant}}

    def test_createObject(self):
        links_object = VnfLcmOpOccLinks(self_link=self.self_link,
                                        list_link=self.list_link,
                                        cancel=self.cancel,
                                        fail=self.fail,
                                        vnf_instance=self.vnf_instance,
                                        grant=self.grant)

        self.assertEqual(links_object.self_link, self.self_link)
        self.assertEqual(links_object.list_link, self.list_link)
        self.assertEqual(links_object.cancel, self.cancel)
        self.assertEqual(links_object.fail, self.fail)
        self.assertEqual(links_object.vnf_instance, self.vnf_instance)
        self.assertEqual(links_object.grant, self.grant)

    def test_createObjectFromRespDict(self):
        links_object = VnfLcmOpOccLinks.from_response_dict(self.links_dict)
        self.assertEqual(links_object.self_link, self.links_dict['self']['href'])
        self.assertEqual(links_object.list_link, self.links_dict['list']['href'])
        self.assertEqual(links_object.cancel, self.links_dict['cancel']['href'])
        self.assertEqual(links_object.fail, self.links_dict['fail']['href'])
        self.assertEqual(links_object.vnf_instance, self.links_dict['vnfInstance']['href'])
        self.assertEqual(links_object.grant, self.links_dict['grant']['href'])

    def test_returnObjectAsDict(self):
        links_object = VnfLcmOpOccLinks.from_response_dict(self.links_dict)
        links_dict = links_object.as_dict()
        self.assertEqual(links_dict['self'], self.links_dict['self'])
        self.assertEqual(links_dict['list'], self.links_dict['list'])
        self.assertEqual(links_dict['cancel'], self.links_dict['cancel'])
        self.assertEqual(links_dict['fail'], self.links_dict['fail'])
        self.assertEqual(links_dict['vnfInstance'], self.links_dict['vnfInstance'])
        self.assertEqual(links_dict['grant'], self.links_dict['grant'])


class TestVmfLcmOpOcc(unittest.TestCase):
    def setUp(self):
        self.operation_id = 'arg1'
        self.operation_state = 'arg2'
        self.state_entered_time = 'arg3'
        self.start_time = 'arg4'
        self.vnf_instance_id = 'arg5'
        self.operation_type = 'arg6'
        self.is_automatic_invocation = 'arg7'
        self.operation_params = 'arg8'
        self.is_cancel_pending = 'arg9'
        self.links = 'arg10'
        self.grant_id = 'arg11'
        self.operation_name = 'arg12'
        self.cancel_mode = 'arg13'
        self.error = 'arg14'
        self.resource_changes = 'arg15'
        self.changed_info = 'arg16'
        self.additional_data = 'arg17'
        self.resp_dict = {'id': self.operation_id, 'operationState': self.operation_state,
                          'stateEnteredTime': self.state_entered_time, 'startTime': self.start_time,
                          'vnfInstanceId': self.vnf_instance_id, 'grantId': self.grant_id,
                          'operation': self.operation_type, 'operationName': self.operation_name,
                          'isAutomaticInvocation': self.is_automatic_invocation,
                          'operationParams': self.operation_params, 'isCancelPending': self.is_cancel_pending,
                          'cancelMode': self.cancel_mode, 'error': self.error, 'resourceChanges': self.resource_changes,
                          'changedInfo': self.changed_info, 'additionalData': self.additional_data,
                          '_links': {'self': {'href': 'arg10'}}}

    def test_createObject(self):
        vloo_object = VnfLcmOpOcc(operation_id=self.operation_id,
                                  operation_state=self.operation_state,
                                  state_entered_time=self.state_entered_time,
                                  start_time=self.start_time,
                                  vnf_instance_id=self.vnf_instance_id,
                                  operation_type=self.operation_type,
                                  is_automatic_invocation=self.is_automatic_invocation,
                                  operation_params=self.operation_params,
                                  is_cancel_pending=self.is_cancel_pending,
                                  links=self.links,
                                  grant_id=self.grant_id,
                                  operation_name=self.operation_name,
                                  cancel_mode=self.cancel_mode,
                                  error=self.error,
                                  resource_changes=self.resource_changes,
                                  changed_info=self.changed_info,
                                  additional_data=self.additional_data)
        self.assertEqual(vloo_object.operation_id, self.operation_id)
        self.assertEqual(vloo_object.operation_state, self.operation_state)
        self.assertEqual(vloo_object.state_entered_time, self.state_entered_time)
        self.assertEqual(vloo_object.start_time, self.start_time)
        self.assertEqual(vloo_object.vnf_instance_id, self.vnf_instance_id)
        self.assertEqual(vloo_object.operation_type, self.operation_type)
        self.assertEqual(vloo_object.is_automatic_invocation, self.is_automatic_invocation)
        self.assertEqual(vloo_object.operation_params, self.operation_params)
        self.assertEqual(vloo_object.is_cancel_pending, self.is_cancel_pending)
        self.assertEqual(vloo_object.links, self.links)
        self.assertEqual(vloo_object.grant_id, self.grant_id)
        self.assertEqual(vloo_object.operation_name, self.operation_name)
        self.assertEqual(vloo_object.cancel_mode, self.cancel_mode)
        self.assertEqual(vloo_object.error, self.error)
        self.assertEqual(vloo_object.resource_changes, self.resource_changes)
        self.assertEqual(vloo_object.changed_info, self.changed_info)
        self.assertEqual(vloo_object.additional_data, self.additional_data)

    def test_createObjectFromRespDict(self):
        vloo_object = VnfLcmOpOcc.from_response_dict(self.resp_dict)
        self.assertEqual(vloo_object.operation_id, self.resp_dict['id'])
        self.assertEqual(vloo_object.operation_state, self.resp_dict['operationState'])
        self.assertEqual(vloo_object.state_entered_time, self.resp_dict['stateEnteredTime'])
        self.assertEqual(vloo_object.start_time, self.resp_dict['startTime'])
        self.assertEqual(vloo_object.vnf_instance_id, self.resp_dict['vnfInstanceId'])
        self.assertEqual(vloo_object.operation_type, self.resp_dict['operation'])
        self.assertEqual(vloo_object.is_automatic_invocation, self.resp_dict['isAutomaticInvocation'])
        self.assertEqual(vloo_object.operation_params, self.resp_dict['operationParams'])
        self.assertEqual(vloo_object.is_cancel_pending, self.resp_dict['isCancelPending'])
        self.assertEqual(vloo_object.links.as_dict(), self.resp_dict['_links'])
        self.assertEqual(vloo_object.grant_id, self.resp_dict['grantId'])
        self.assertEqual(vloo_object.operation_name, self.resp_dict['operationName'])
        self.assertEqual(vloo_object.cancel_mode, self.resp_dict['cancelMode'])
        self.assertEqual(vloo_object.error, self.resp_dict['error'])
        self.assertEqual(vloo_object.resource_changes, self.resp_dict['resourceChanges'])
        self.assertEqual(vloo_object.changed_info, self.resp_dict['changedInfo'])
        self.assertEqual(vloo_object.additional_data, self.resp_dict['additionalData'])

    def test_returnObjectAsDict(self):
        vloo_object = VnfLcmOpOcc.from_response_dict(self.resp_dict)
        vloo_dict = vloo_object.as_dict()

        for k in self.resp_dict.keys():
            with self.subTest():
                self.assertEqual(vloo_dict[k], self.resp_dict[k])
